function moveHorizontal(player, axis, speed, dt) {
  const input = Math.max(-1, Math.min(1, axis));
  player.x += input * speed * dt;
  return player.x;
}

function jumpVelocity(vy, grounded, pressed, impulse) {
  if (grounded && pressed) return -Math.abs(impulse);
  return vy;
}

function gravityStep(body, gravity, dt) {
  body.vy += gravity * dt;
  body.y += body.vy * dt;
  return body;
}

function rectanglesOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
    a.y < b.y + b.h && a.y + a.h > b.y;
}

function applyDamage(hp, damage, maxHp) {
  const safeMax = Math.max(0, maxHp);
  return Math.max(0, Math.min(safeMax, hp - Math.max(0, damage)));
}

function patrolStep(x, direction, speed, dt, minX, maxX) {
  const next = x + direction * speed * dt;
  if (next <= minX) return { x: minX, direction: 1 };
  if (next >= maxX) return { x: maxX, direction: -1 };
  return { x: next, direction };
}

function collectNearby(player, item, radius) {
  const dx = player.x - item.x;
  const dy = player.y - item.y;
  if (dx * dx + dy * dy > radius * radius) return false;
  item.taken = true;
  return true;
}

function advanceTimer(remaining, dt) {
  return Math.max(0, remaining - Math.max(0, dt));
}

function transitionState(state, startPressed, elapsed, windupDuration) {
  if (state === "idle" && startPressed) return "windup";
  if (state === "windup" && elapsed >= windupDuration) return "active";
  return state;
}

function springResponse(vy, touchingSpring, launchSpeed) {
  if (touchingSpring && vy >= 0) return -Math.abs(launchSpeed);
  return vy;
}

function movePlatformToward(position, target, speed, dt) {
  const step = Math.max(0, speed * dt);
  const difference = target - position;
  if (Math.abs(difference) <= step) return target;
  return position + Math.sign(difference) * step;
}
